// ── Dynamic + weak: JavaScript coercions ──────────────────────
let x = 42;
x = 'hello';          // fine — JS variables hold any type
x = [1, 2, 3];        // still fine

// Infamous weak-typing coercions
console.log('3' + 3);         // '33'  — number coerced to string
console.log('3' - 1);         // 2     — string coerced to number
console.log([] == false);     // true  — both coerce to 0
console.log(null == undefined); // true — special rule
console.log(!!'' == false);   // true  — empty string is falsy

// ── Dynamic + strong: Python-style enforcement (simulated) ────
function strictAdd(a, b) {
  if (typeof a !== typeof b) {
    throw new TypeError(
      `Cannot add ${typeof a} and ${typeof b} — use explicit conversion`
    );
  }
  return a + b;
}
console.log(strictAdd(3, 4));     // 7
console.log(strictAdd('a', 'b')); // 'ab'
try {
  strictAdd(3, '4');
} catch (e) {
  console.log(e.message);
  // Cannot add number and string — use explicit conversion
}

// ── Type inference (TypeScript concepts, shown with comments) ──
// const n    = 42;            // inferred: number
// const s    = 'hello';       // inferred: string
// const flag = true;          // inferred: boolean
// const nums = [1, 2, 3];     // inferred: number[]
// const obj  = { x: 0, y: 0 }; // inferred: { x: number; y: number }
//
// function double(n: number) { return n * 2; }
// // return type inferred as number from the expression n * 2

// ── Generic-style identity function ───────────────────────────
// TypeScript: function identity<T>(x: T): T { return x; }
// Called as identity(42)   -> T inferred as number, returns number
// Called as identity('hi') -> T inferred as string, returns string

// Simulated in JS with a runtime tag check:
function identity(x) {
  // No compile-time guarantee, but same structure
  return x;
}
console.log(identity(42));     // 42
console.log(identity('hello')); // 'hello'
console.log(identity([1,2,3])); // [1,2,3]

// ── Generic constraint (TypeScript pattern) ───────────────────
// function getLength<T extends { length: number }>(x: T): number {
//   return x.length;
// }
// getLength('hello');    // 5   — string has .length
// getLength([1,2,3]);    // 3   — array has .length
// getLength(42);         // ERROR: number has no .length property

// Runtime simulation of the same constraint:
function getLength(x) {
  if (x === null || x === undefined || typeof x.length !== 'number') {
    throw new TypeError(`Value has no numeric .length: ${JSON.stringify(x)}`);
  }
  return x.length;
}
console.log(getLength('hello'));   // 5
console.log(getLength([1,2,3]));   // 3
try {
  getLength(42);
} catch (e) {
  console.log(e.message); // Value has no numeric .length: 42
}

// ── Structural typing: shape compatibility ────────────────────
// TypeScript uses structural typing — shape is what matters, not name.
//
// interface Named { name: string; }
// function greet(person: Named): string {
//   return `Hello, ${person.name}!`;
// }
// const user = { name: 'Alice', age: 30, role: 'admin' };
// greet(user); // VALID — user has name: string (and more)
//
// Nominal equivalent (Java): greet() would require user to
// explicitly implement Named, even with identical fields.

// Runtime structural check simulation:
function greet(person) {
  if (typeof person !== 'object' || typeof person.name !== 'string') {
    throw new TypeError('Expected object with name: string');
  }
  return `Hello, ${person.name}!`;
}
console.log(greet({ name: 'Alice', age: 30 })); // Hello, Alice!
try {
  greet({ fullName: 'Bob' });  // missing .name
} catch(e) {
  console.log(e.message); // Expected object with name: string
}

// ── Union types and narrowing ─────────────────────────────────
// TypeScript: function describe(x: string | number): string
function describe(x) {
  if (typeof x === 'string') {
    // TypeScript narrows x to string here
    return `String of length ${x.length}: "${x}"`;
  }
  if (typeof x === 'number') {
    // TypeScript narrows x to number here
    return `Number: ${x.toFixed(2)}`;
  }
  throw new TypeError(`Unexpected type: ${typeof x}`);
}
console.log(describe('hello')); // String of length 5: "hello"
console.log(describe(3.14159)); // Number: 3.14

// ── Branded types pattern (nominal simulation in TypeScript) ──
// type UserId   = string & { _brand: 'UserId' };
// type AccountId = string & { _brand: 'AccountId' };
//
// function createUserId(id: string): UserId {
//   return id as UserId;
// }
// function fetchUser(id: UserId): User { ... }
//
// const uid = createUserId('u_123');
// const aid = 'a_456' as AccountId;
// fetchUser(uid);  // OK
// fetchUser(aid);  // ERROR: AccountId is not assignable to UserId
// — Even though both are strings at runtime, the brand makes them
//   incompatible in the type system, preventing mix-ups.

// ── Language comparison table ─────────────────────────────────
const languages = [
  { lang: 'TypeScript', static: true,  strong: 'mostly', sound: false, notes: 'Structural; unsound via any/as' },
  { lang: 'Python',     static: false, strong: true,     sound: 'N/A', notes: 'Dynamic+strong; mypy for static analysis' },
  { lang: 'JavaScript', static: false, strong: false,    sound: 'N/A', notes: 'Dynamic+weak; infamous coercions' },
  { lang: 'Java',       static: true,  strong: true,     sound: 'mostly', notes: 'Nominal; generics erased at runtime' },
  { lang: 'Haskell',    static: true,  strong: true,     sound: true,  notes: 'HM inference; purely functional' },
  { lang: 'Rust',       static: true,  strong: true,     sound: true,  notes: 'Ownership+types; safe code is sound' },
  { lang: 'C',          static: true,  strong: false,    sound: false, notes: 'Static+weak; pointer casts break safety' }
];
console.table(languages.map(({ lang, static: s, strong, sound, notes }) =>
  ({ Language: lang, Static: s, Strong: strong, Sound: sound, Notes: notes })));

sections.content:
One of the most practically important features of a static type system is **type narrowing**: within a conditional branch, the compiler refines the type of a variable based on the check performed.

In TypeScript, if a variable has type `string | number | null`, then inside the block `if (typeof x === 'string') { ... }` the compiler knows `x` is `string` — you can safely call `.toUpperCase()` without a cast. After `if (x !== null) { ... }`, the compiler knows `x` is `string | number`. The control flow narrows the type progressively.

**Type guards** are functions that return a **type predicate** — a function whose return type is `x is SomeType`. This tells the compiler that if the function returns true, the argument is of that specific type:

```typescript
function isString(x: unknown): x is string {
  return typeof x === 'string';
}
```

This lets you factor narrowing logic into reusable functions while preserving the compiler's ability to narrow types at call sites.

**Discriminated unions** (also called tagged unions or sum types) combine union types with a common literal `kind` field that the compiler can use to narrow automatically:

```typescript
type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rectangle'; width: number; height: number };

function area(s: Shape): number {
  switch (s.kind) {
    case 'circle': return Math.PI * s.radius ** 2; // s narrowed to circle
    case 'rectangle': return s.width * s.height;   // s narrowed to rectangle
  }
}
```

Discriminated unions are a pattern from functional programming (where they are called *algebraic data types*) that has spread into TypeScript, Rust (`enum`), Swift, Kotlin, and others. They provide an exhaustive, type-safe way to model data that can take one of several distinct shapes — a much better alternative to `any`, `Object`, or nullable fields.
